pair I=(a*A+bb*B+c*C)/(a+bb+c);
real r=I.y;
pair Pa=C+dot(I-C,unit(A-C))*unit(A-C),Pb=C+dot(I-C,unit(B-C))*unit(B-C);
draw(A--B--C--cycle,linewidth(0.9));
draw(circle(I,r),blue);dot(I);
