draw(arc(C,1.0,degrees(Pa-C),degrees(I-C)),linewidth(0.6));
label("$\dfrac {C}{2}$",C+1.6*dir((degrees(Pa-C)+degrees(I-C))/2),fontsize(8pt));
label("$A$",A,SW);label("$B$",B,SE);label("$C$",C,N);label("$I$",I,S);
label("$r$",(I+Pa)/2,N,red);label("$r$",(I+Pb)/2,S,red);
label("$s-c$",(C+Pa)/2,W);label("$s-c$",(C+Pb)/2,NE);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

The incentre lies on the bisector of angle $C$, so in the right triangle $CPI$ (right angle at $P$, since a radius is perpendicular to the tangent) we have $\angle PCI=\dfrac {C}{2}$ and
\[
\dfrac{s-c}{r}=\dfrac{CP}{IP}=\cot\dfrac {C}{2} .
\]
Finally, using $\cos C=2\cos^2\dfrac {C}{2}-1$ and $\sin C=2\sin\dfrac {C}{2}\cos\dfrac {C}{2}$,
\[
\cot C+\csc C=\dfrac{1+\cos C}{\sin C}=\dfrac{2\cos^2\dfrac {C}{2}}{2\sin\dfrac {C}{2}\cos\dfrac {C}{2}}=\cot\dfrac {C}{2} .
\]
Hence $\dfrac{s-c}{r}=\cot C+\csc C$. $\blacksquare$

\textbf{Symmetry.} The reflection in the altitude from $A$ swaps $B$ and $C$ and maps the two trisectors of $\angle A$ to each other, so it swaps $D$ and $E$. Hence $BE=CD=5$ and $AE=AD$; call this length $x$. The points lie in the order $B,E,D,C$ with $EC=6$.

\textbf{Triangle $AEC$.} Since $\angle EAD=\angle DAC$, segment $AD$ bisects $\angle EAC$. By the angle bisector theorem,
\[
\dfrac{ED}{DC}=\dfrac{AE}{AC}\quad\Longrightarrow\quad AC=5x .
\]
By Stewart's theorem for the cevian $AD$ in triangle $AEC$ (with $ED=1$, $DC=5$, $EC=6$):
\[
AE^2\cdot DC+AC^2\cdot ED=EC\left(AD^2+ED\cdot DC\right)\ \Longrightarrow\ 5x^2+25x^2=6(x^2+5)\ \Longrightarrow\ x^2=\dfrac{5}{4} .
\]
So $x=\dfrac{\sqrt5}{2}$ and $AC=5x=\boxed{\dfrac{5\sqrt5}{2}}$.

