label("$A$",A,NW);label("$B$",B,NE);label("$C$",C,SE);label("$D$",D,SW);label("$O$",O,S);
label("$E$",Ep,SW);label("$F$",F,SE);label("$G$",G,NE);label("$H$",H,NW);
label("$k$",r*dir(200),W);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Since $G$ lies on $k$,
\[
\dfrac{s^2}{4}+(1+s)^2=2\ \Longrightarrow\ 5s^2+8s-4=0\ \Longrightarrow\ (5s-2)(s+2)=0,
\]
so $s=\dfrac{2}{5}$. The ratio of the areas is
\[
\dfrac{s^2}{2^2}=\dfrac{4}{25}\cdot\dfrac{1}{4}=\boxed{\dfrac{1}{25}} .
\]

One diagonal is $4.5\text{ dm}=45$ cm. The area of a rhombus is half the product of its diagonals, so the other diagonal is $\dfrac{2\cdot540}{45}=24$ cm. The diagonals bisect each other at right angles at $O$, so $OA=22.5$ cm and $OB=12$ cm, and the side is
\[
AB=\sqrt{22.5^2+12^2}=\sqrt{650.25}=25.5\text{ cm}.
\]

\begin{asy}
usepackage("amsmath");
size(7cm);
defaultpen(fontsize(10pt));
