label("$22.5$",(11.25,0),S);label("$12$",(0,-6),E);label("$h$",(O+H)/2,NE,red);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Let $h=OH$ be the distance from $O$ to side $AB$. Computing the area of the right triangle $AOB$ in two ways,
\[
\dfrac{1}{2}\cdot22.5\cdot12=\dfrac{1}{2}\cdot25.5\cdot h\ \Longrightarrow\ h=\dfrac{270}{25.5}=\boxed{\dfrac{180}{17}\text{ cm}}\approx10.6\text{ cm}.
\]
By symmetry the distance to each of the four sides is the same.

When $B$ lands on $D$, every point of the crease is equidistant from $B$ and $D$, so the crease $EF$ is the perpendicular bisector of $BD$. Let it meet $BD$ at $O$, the midpoint of $BD$. Since $BD=\sqrt{8^2+6^2}=10$, $OD=5$.

\begin{asy}
usepackage("amsmath");
